SELECT 
FROM hr_request r JOIN employee e ON e.id = r.employee_id
WHERE r.id = #{id}

    AND 1 = 1
    AND e.department_id = #{departmentId}
    AND e.id = #{employeeId}
    AND 1 = 0

LIMIT 1

SELECT 
FROM hr_request r JOIN employee e ON e.id = r.employee_id
WHERE 1 = 1
AND r.request_type = #{requestType}
AND r.status = #{status}
AND r.employee_id = #{employeeId}
AND e.department_id = #{departmentId}

    AND 1 = 1
    AND e.department_id = #{departmentId}
    AND e.id = #{employeeId}
    AND 1 = 0

ORDER BY r.created_at DESC, r.id DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM hr_request r JOIN employee e ON e.id = r.employee_id
WHERE 1 = 1
AND r.request_type = #{requestType}
AND r.status = #{status}
AND r.employee_id = #{employeeId}
AND e.department_id = #{departmentId}

    AND 1 = 1
    AND e.department_id = #{departmentId}
    AND e.id = #{employeeId}
    AND 1 = 0

